String sortNumbers(String numbers) {
  final Map<String, int> valueMap = {
    'zero': 0,
    'one': 1,
    'two': 2,
    'three': 3,
    'four': 4,
    'five': 5,
    'six': 6,
    'seven': 7,
    'eight': 8,
    'nine': 9
  };

  final List<String> words = numbers.split(' ').where((x) => x.isNotEmpty).toList();
  words.sort((a, b) => valueMap[a]!.compareTo(valueMap[b]!));
  return words.join(' ');
}

