List<int> removeDuplicates(List<int> numbers) {
  Map<int, int> counts = {};

  for (int n in numbers) {
    counts[n] = (counts[n] ?? 0) + 1;
  }

  return numbers.where((n) => counts[n]! <= 1).toList();
}

