@pragma('vm:entry-point')
List<int> countUpTo(int n) {
  List<int> primes = [];
  for (int i = 2; i < n; i++) {
    bool isPrime = true;
    for (int j = 2; j < i; j++) {
      if (i % j == 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) {
      primes.add(i);
    }
  }
  return primes;
}

@pragma('vm:entry-point')
void main() {
  print(countUpTo(5));
  print(countUpTo(11));
  print(countUpTo(0));
  print(countUpTo(20));
  print(countUpTo(1));
  print(countUpTo(18));
}

