String exchange(List<int> lst1, List<int> lst2) {
  int odd = 0;
  int even = 0;

  for (int i in lst1) {
    if (i % 2 == 1) {
      odd += 1;
    }
  }

  for (int i in lst2) {
    if (i % 2 == 0) {
      even += 1;
    }
  }

  if (even >= odd) {
    return "YES";
  }
  return "NO";
}

